<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
const route=useRoute()
import {ApiError} from '../../api/http'
import PageHeader from '../../components/common/PageHeader.vue'
import AppSelect from '../../components/common/AppSelect.vue'
import {ops,type Identity,type Draft} from '../../api/operations'
const card=ref<Identity|null>(null),tab=ref('tasks'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const drafts=ref<Draft[]>([]),selected=ref<Draft|null>(null),residents=ref<any[]>([]),staff=ref<any[]>([]),executions=ref<any[]>([]),shifts=ref<any[]>([]),corrections=ref<any[]>([]),audit=ref<any[]>([]),dashboard=ref<any>(null),catalog=ref<any>(null),constraints=ref<any>(null),recipes=ref<any>(null)
const issueNames:Record<string,string>={dose_limit:'剂量超过已核实上限',dose_limit_unknown:'缺少剂量上限依据',polypharmacy:'多重用药成分冲突',duplicate_active_ingredient:'不同药品含有重复活性成分',drug_allergen_conflict:'药品含已知过敏原',food_drug_conflict:'食物与在用药存在冲突',allergen_conflict:'含已知过敏原',energy_target:'未满足已核实的一日能量范围',protein_target:'蛋白质不足',sodium_limit:'钠含量超限',unknown_drug:'药品尚未核实',unknown_food:'食物尚未核实',unknown_disease:'疾病标识未纳入已核实图谱',unknown_allergen:'过敏原标识未纳入已核实图谱',missing_or_expired_evidence:'证据缺失或过期'}
const blocked=ref<string[]>([])
const names:Record<string,string>={medication:'用药草稿',menu:'一日配餐草稿',schedule:'护理排班',payroll:'月度核薪',meal_swap:'换餐申请',incident:'照护上报'}
const states:Record<string,string>={pending:'待确认',approved:'已批准',rejected:'已退回',expired:'已过期',completed:'已完成'}
const nodeNames:Record<string,string>={gateway:'岗位权限检查',supervisor:'协作任务分派',evidence:'查证资料',precheck:'规则预校验',role_agent:'岗位助手整理',critic:'草稿复校',human_interrupt:'等待人工核对',approval_recheck:'审批前复验',execution_created:'生成执行清单'}
const task=ref(''),target=ref(''),instruction=ref(''),useModel=ref(true),rationale=ref(''),menuTitle=ref(''),note=ref(''),month=ref(`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}`),observation=ref(''),severity=ref('routine')
const meds=ref([{drug_id:'',mg_per_dose:'',times_daily:1}]),foods=ref([{food_id:'',grams:''}]),plannedShifts=ref([{account_id:'',start_at:'',end_at:'',hourly_rate:''}])
const serviceDate=ref(`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}-${String(new Date().getDate()).padStart(2,'0')}`)
const editId=ref(''),editVersion=ref(0),revisionReason=ref(''),revisionRoute=ref('agent'),revisionTag=ref('other')
const recordExcerpt=ref<Record<string,string>|null>(null)
const profileVersion=ref(0),residentVersion=ref(0),allergens=ref(''),diseases=ref(''),energyMin=ref(''),energyMax=ref(''),proteinMin=ref(''),sodiumMax=ref(''),profileSource=ref(''),known=ref(false)
const referenceDrug=ref(''),referenceChunk=ref(''),referenceSection=ref(''),referenceFrom=ref(''),referenceUntil=ref('')
const newRole=ref('user'),staffTarget=ref(''),qualification=ref(''),validUntil=ref('')
const tabs=computed(()=>[
 ...(card.value?.tasks.length?[{id:'tasks',title:'发起任务'}]:[]),{id:'drafts',title:card.value?.role==='admin'?'审批台':'草稿与确认'},
 ...(['admin','medical','nursing','kitchen','user'].includes(card.value?.role||'')?[{id:'executions',title:'执行清单'}]:[]),
 ...(['admin','nursing','finance','user'].includes(card.value?.role||'')?[{id:'shifts',title:'排班与打卡'}]:[]),
 ...(card.value?.role==='medical'?[{id:'profiles',title:'医护资料核实'}]:[]),
 ...(['admin','nursing'].includes(card.value?.role||'')?[{id:'corrections',title:'修正台账'}]:[]),
 ...(card.value?.role==='admin'?[{id:'references',title:'药品原文定位'},{id:'dashboard',title:'运营看板'},{id:'staff',title:'岗位与资质'},{id:'audit',title:'操作留痕'}]:[])
])
function split(s:string){return [...new Set(s.split(/[,，、\n]/).map(v=>v.trim()).filter(Boolean))]}
function dateText(s:string){return s?new Date(s.endsWith('Z')?s:s+'Z').toLocaleString('zh-CN'):''}
function describe(value:unknown):string{if(Array.isArray(value))return value.map(describe).join('；');if(value&&typeof value==='object')return Object.entries(value).filter(([k])=>!['resident_id','account_id','constraint_token'].includes(k)).map(([k,v])=>`${({drug_id:'药品',mg_per_dose:'单次mg',times_daily:'每日次数',food_id:'食物',grams:'克',title:'名称',kind:'业务',medicines:'用药',foods:'餐食',rationale:'依据',reason:'原因',observation:'观察记录',severity:'级别',hourly_rate:'时薪',start_at:'上班',end_at:'下班',month:'月份',service_date:'服务日期',amount:'金额',seconds:'秒',shifts:'班次',note:'说明',name:'姓名',energy:'能量kcal',protein:'蛋白g',sodium:'钠mg',formula:'计算口径',lines:'核算明细',pending:'待补打卡',sources:'工时依据'} as Record<string,string>)[k]||k}：${describe(v)}`).join(' · ');return value==null?'未记录':String(value)}
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';blocked.value=[];try{await work()}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError){const d=e.detail as {validation?:{issues?:{code:string}[]}};blocked.value=(d?.validation?.issues||[]).map(i=>issueNames[i.code]||'存在需专业核对的规则问题')}}finally{busy.value=false}}
async function loadDrafts(){drafts.value=(await ops.list<Draft>('drafts')).items}
async function init(){loading.value=true;try{card.value=await ops.identity();task.value=card.value.tasks[0]||'';tab.value=card.value.tasks.length?'tasks':'drafts';await loadDrafts();if(['admin','medical','nursing','user'].includes(card.value.role))residents.value=(await ops.list('residents')).items;if(typeof route.query.resident_id==='string'&&residents.value.some(r=>r.id===route.query.resident_id))target.value=route.query.resident_id;if(typeof route.query.task==='string'&&card.value.tasks.includes(route.query.task))task.value=route.query.task;if(['admin','nursing'].includes(card.value.role))staff.value=(await ops.list('staff')).items}catch(e){error.value=e instanceof Error?e.message:'工作台加载失败'}finally{loading.value=false}}
async function changeTab(id:string){tab.value=id;selected.value=null;await action(async()=>{if(id==='drafts')await loadDrafts();if(id==='executions')executions.value=(await ops.list('executions')).items;if(id==='shifts')shifts.value=(await ops.list('shifts')).items;if(id==='corrections')corrections.value=(await ops.list('corrections')).items;if(id==='dashboard')dashboard.value=await ops.get('dashboard');if(id==='audit')audit.value=(await ops.list('audit')).items})}
async function getCatalog(){await action(async()=>{catalog.value=await ops.get('catalog')})}
async function getConstraints(){await action(async()=>{constraints.value=await ops.post('constraints');notice.value='已获取脱敏约束，请在有效期内提交配餐。'})}
function payload(){switch(task.value){case 'medication':return {resident_id:target.value,medicines:meds.value,rationale:rationale.value};case 'menu':return {service_date:serviceDate.value,constraint_token:constraints.value?.constraint_token,foods:foods.value,title:menuTitle.value};case 'meal_swap':return {service_date:serviceDate.value,resident_id:target.value,foods:foods.value,reason:rationale.value};case 'incident':return {resident_id:target.value,severity:severity.value,observation:observation.value};case 'schedule':return {shifts:plannedShifts.value};case 'payroll':return {month:month.value};default:throw Error('请选择任务')}}
async function submit(){await action(async()=>{if(editId.value){selected.value=await ops.put(`drafts/${editId.value}`,{version:editVersion.value,payload:payload(),route:revisionRoute.value,tag:revisionTag.value,reason:revisionReason.value});editId.value=''}else selected.value=await ops.run(task.value,payload(),useModel.value,instruction.value);await loadDrafts();tab.value='drafts';notice.value='草稿已保存，等待有权限的人员确认。'})}
function startEdit(row:Draft){selected.value=null;editId.value=row.id;editVersion.value=row.version;task.value=row.kind;const p=row.current;serviceDate.value=p.service_date||serviceDate.value;target.value=p.resident_id||'';meds.value=p.medicines?structuredClone(p.medicines):meds.value;foods.value=p.foods?structuredClone(p.foods):foods.value;rationale.value=p.rationale||p.reason||'';menuTitle.value=p.title||'';if(p.constraint_token)constraints.value={constraint_token:p.constraint_token};if(p.shifts)plannedShifts.value=structuredClone(p.shifts);month.value=p.month||month.value;observation.value=p.observation||'';severity.value=p.severity||'routine';tab.value='tasks';revisionReason.value=''}
async function decide(kind:string){if(!selected.value)return;const row=selected.value;if(!window.confirm(kind==='approve'?'确认已核对依据并批准？':'确认退回该草稿？'))return;await action(async()=>{selected.value=await ops.post(`drafts/${row.id}/decision`,{version:row.version,action:kind,note:note.value});note.value='';await loadDrafts();notice.value='处理结果已保存。'})}
async function loadProfile(){await action(async()=>{if(!target.value)throw Error('请先选择老人');const data=await ops.get(`profiles/${target.value}`);recordExcerpt.value=data.record_excerpt;profileVersion.value=data.version;residentVersion.value=data.resident_version;const p=data.profile;allergens.value=p?.allergens?.join('、')||'';diseases.value=p?.diseases?.join('、')||'';meds.value=p?.medicines||[{drug_id:'',mg_per_dose:'',times_daily:1}];energyMin.value=p?.energy_min||'';energyMax.value=p?.energy_max||'';proteinMin.value=p?.protein_min||'';sodiumMax.value=p?.sodium_max||'';profileSource.value=p?.source||'';known.value=false;notice.value='请逐项核实，空白列表仅在明确无已知项时确认。'})}
async function saveProfile(){await action(async()=>{if(!known.value||!residentVersion.value)throw Error('请先读取并明确核实资料');const result=await ops.put(`profiles/${target.value}`,{version:profileVersion.value,resident_version:residentVersion.value,allergens:split(allergens.value),diseases:split(diseases.value),medicines:meds.value.filter(m=>m.drug_id),energy_min:energyMin.value,energy_max:energyMax.value,protein_min:proteinMin.value,sodium_max:sodiumMax.value,source:profileSource.value});profileVersion.value=result.version;notice.value='结构化医护资料已核实保存。'})}
onMounted(init)
</script>
<template><div class="page operations"><PageHeader :title="`${card?.role_name||'协作'}工作台`" subtitle="专业建议经过规则校验、人工确认，再进入执行。"/><p v-if="loading" role="status">正在核对岗位权限…</p><p v-if="error" class="ops-alert error" role="alert">{{ error }}</p><p v-if="notice" class="ops-alert success" role="status">{{ notice }}</p>
<ul v-if="blocked.length" class="ops-alert error"><li v-for="(b,i) in blocked" :key="i">{{ b }}</li></ul><template v-if="card"><section class="ops-identity"><div><span class="ops-kicker">禾龄通 · 协同照护</span><h2>{{ card.name }}，今天从这里开始</h2><p>{{ card.role_name }} · {{ card.tools.length }} 类授权工具<span v-if="['medical','nursing'].includes(card.role)"> · {{ card.qualified?'资质有效':'资质未核实或已过期' }}</span></p></div><span class="ops-seal"><AppIcon name="shield" :size="28"/>按岗授权 · 全程留痕</span></section>
<nav class="ops-tabs" aria-label="岗位业务"><button v-for="t in tabs" :key="t.id" class="btn" :class="{primary:tab===t.id}" :disabled="busy" :aria-pressed="tab===t.id" @click="changeTab(t.id)">{{ t.title }}</button></nav>
<form v-if="tab==='tasks'" class="card ops-panel" @submit.prevent="submit"><h2>{{ editId?'修改待确认草稿':'发起协作任务' }}</h2><fieldset :disabled="busy" class="ops-fieldset"><div class="ops-grid"><label>任务<AppSelect v-model="task" class="select" :disabled="!!editId"><option v-for="id in card.tasks" :key="id" :value="id">{{ names[id] }}</option></AppSelect></label><label v-if="['medication','meal_swap','incident'].includes(task)">负责对象<AppSelect v-model="target" class="select" :disabled="!!editId"><option value="">请选择老人</option><option v-for="r in residents" :key="r.id" :value="r.id">{{ r.name }} · {{ r.location||'位置未登记' }}</option></AppSelect></label><label v-if="task==='payroll'">核薪月份<input v-model="month" class="input" type="month" required></label></div>
<template v-if="['medication','menu','meal_swap'].includes(task)"><div class="ops-actions"><button type="button" class="btn" @click="getCatalog">读取有效{{ task==='medication'?'药品':'食物' }}目录</button><button v-if="task==='menu'" type="button" class="btn" @click="getConstraints">获取全院脱敏约束</button><button v-if="task==='menu'" type="button" class="btn" @click="action(async()=>{recipes=await ops.get('recipes')})">查找外部食谱参考</button></div><p v-if="catalog?.demo" class="ops-alert">当前目录为虚构演示事实，禁止用于真实诊疗或配餐。</p><p v-if="constraints">约束对象 {{ constraints.population||'已选择' }} 人 · {{ constraints.rule_version }} · 已知过敏原 {{ constraints.allergens?.join('、')||'见专业核实资料' }}。不展示个人或药品标识。</p><details v-if="recipes"><summary>食谱参考 {{ recipes.count }} 份</summary><p v-for="r in recipes.recipes" :key="r.id">{{ r.name }} · {{ r.ingredients.join('、') }}</p></details></template>
<div v-if="task==='medication'" class="ops-stack"><div v-for="(m,i) in meds" :key="i" class="ops-line"><label>药品<AppSelect v-model="m.drug_id" class="select"><option value="">请选择有效药品</option><option v-for="d in catalog?.drugs||[]" :key="d.id" :value="d.id">{{ d.name }}</option><option v-if="m.drug_id&&!catalog" :value="m.drug_id">{{ m.drug_id }}</option></AppSelect></label><label>单次剂量（mg）<input v-model="m.mg_per_dose" class="input" type="number" step="0.01" min="0.01" required></label><label>每日次数<input v-model.number="m.times_daily" class="input" type="number" min="1" max="24" required></label><button v-if="meds.length>1" type="button" class="btn" @click="meds.splice(i,1)">移除</button></div><button type="button" class="btn" @click="meds.push({drug_id:'',mg_per_dose:'',times_daily:1})">添加药品</button></div>
<div v-if="['menu','meal_swap'].includes(task)" class="ops-stack"><label>餐食服务日期<input v-model="serviceDate" class="input" type="date" required></label><p class="ops-help">营养阈值按已核实的一日目标校验，请填入一日完整配餐的食物总量。单餐替换需先形成完整一日配餐方案。</p><label v-if="task==='menu'">配餐名称<input v-model="menuTitle" class="input" maxlength="100" required></label><div v-for="(f,i) in foods" :key="i" class="ops-line"><label>已核实食物<AppSelect v-model="f.food_id" class="select"><option value="">请选择食物</option><option v-for="item in catalog?.foods||[]" :key="item.id" :value="item.id">{{ item.name }}</option><option v-if="f.food_id&&!catalog" :value="f.food_id">{{ f.food_id }}</option></AppSelect></label><label>每日总量（克）<input v-model="f.grams" class="input" type="number" min="0.01" step="0.01" required></label><button v-if="foods.length>1" type="button" class="btn" @click="foods.splice(i,1)">移除</button></div><button type="button" class="btn" @click="foods.push({food_id:'',grams:''})">添加食物</button></div>
<div v-if="task==='schedule'" class="ops-stack"><div v-for="(s,i) in plannedShifts" :key="i" class="ops-line"><label>护工<AppSelect v-model="s.account_id" class="select"><option value="">请选择护工</option><option v-for="person in staff.filter(p=>p.role==='user')" :key="person.id" :value="person.id">{{ person.name }}</option></AppSelect></label><label>上班（北京时间）<input v-model="s.start_at" class="input" type="datetime-local" required></label><label>下班（北京时间）<input v-model="s.end_at" class="input" type="datetime-local" required></label><label>小时费率（元）<input v-model="s.hourly_rate" class="input" type="number" step="0.01" min="0.01" required></label><button v-if="plannedShifts.length>1" type="button" class="btn" @click="plannedShifts.splice(i,1)">移除</button></div><button type="button" class="btn" @click="plannedShifts.push({account_id:'',start_at:'',end_at:'',hourly_rate:''})">添加班次</button></div>
<label v-if="['medication','meal_swap'].includes(task)">{{ task==='medication'?'专业建议依据':'换餐原因' }}<textarea v-model="rationale" class="input" rows="3" maxlength="1000" required/></label><template v-if="task==='incident'"><label>上报级别<AppSelect v-model="severity" class="select"><option value="routine">日常观察</option><option value="urgent">紧急情况（同时立即联系医护）</option></AppSelect></label><label>观察记录<textarea v-model="observation" class="input" rows="4" maxlength="2000" required/></label><p class="ops-help">上报不能替代现场应急处置。紧急情况请立即联系值班医护。</p></template>
<template v-if="editId"><div class="ops-grid"><label>改进方向<AppSelect v-model="revisionRoute" class="select"><option value="rule">规则维护</option><option value="agent">Agent改进</option><option value="training">人员培训</option></AppSelect></label><label>原因标签<AppSelect v-model="revisionTag" class="select"><option v-for="t in ['evidence','dose','nutrition','scope','format','workflow','other']" :key="t" :value="t">{{ {evidence:'证据',dose:'剂量',nutrition:'营养',scope:'权限',format:'格式',workflow:'流程',other:'其他'}[t] }}</option></AppSelect></label></div><label>修改依据<textarea v-model="revisionReason" class="input" maxlength="1000" required/></label></template><label v-else class="ops-checkbox"><input v-model="useModel" type="checkbox">由岗位Agent整理草稿说明（不会改变输入数值或校验结论）</label><div class="ops-actions"><button class="btn primary" :disabled="busy">{{ busy?'校验处理中…':editId?'复校并保存修改':'校验并生成待确认草稿' }}</button><button v-if="editId" type="button" class="btn" @click="editId=''">取消修改</button></div></fieldset></form>
<section v-if="tab==='drafts'" class="ops-drafts"><div class="card ops-panel"><h2>任务草稿</h2><p v-if="!drafts.length" class="ops-help">暂无可查看的草稿。</p><button v-for="d in drafts" :key="d.id" class="ops-draft-item" :class="{chosen:selected?.id===d.id}" @click="selected=d;note=''" :disabled="busy"><span><b>{{ names[d.kind] }}</b><small>{{ dateText(d.created_at) }}</small></span><span>{{ states[d.status]||d.status }} · {{ d.risk }}级</span></button></div><article v-if="selected" class="card ops-panel"><h2>{{ names[selected.kind] }} · 核对详情</h2><p v-if="selected.resident_name">服务对象：<b>{{ selected.resident_name }}</b></p><p>有效期至 {{ dateText(selected.expires_at) }} · 第 {{ selected.version }} 版</p><p class="ops-alert" v-if="selected.validation.demo">虚构演示规则，不能作为真实业务决定。</p><div v-for="(step,i) in selected.trace.filter(s=>s.summary)" :key="i" class="ops-help"><b>岗位助手说明</b><p>{{ step.summary }}</p></div><h3>原始建议</h3><p class="ops-content">{{ describe(selected.proposed) }}</p><h3>当前方案</h3><p class="ops-content">{{ describe(selected.current) }}</p><template v-if="selected.kind==='payroll'"><h3>代码核薪结果</h3><p class="ops-content">{{ describe(selected.calculation) }}</p></template><h3>校验依据</h3><p>{{ selected.validation.passed?'通过':'未通过' }} · 规则 {{ selected.validation.rule_version }}</p><p v-if="selected.validation.nutrients">每日营养计算：{{ describe(selected.validation.nutrients) }}</p><ul><li v-for="r in selected.validation.references" :key="r.id">{{ r.section }} · {{ r.location }}：{{ r.quote }}</li></ul><p v-for="(p,i) in selected.validation.paths" :key="i">冲突路径：{{ p.nodes.join(' → ') }}；{{ p.evidence.quote }}</p><details v-if="selected.trace.some(s=>s.citations?.length)"><summary>说明书原文引用</summary><p v-for="(r,i) in selected.trace.flatMap(s=>s.citations||[])" :key="i">{{ r.section }} · {{ r.location }}：{{ r.quote }}</p></details><details><summary>协作处理轨迹</summary><ol><li v-for="(s,i) in selected.trace" :key="i">{{ nodeNames[s.node]||s.node }}</li></ol></details><button v-if="selected.can_edit&&selected.status==='pending'" class="btn" :disabled="busy" @click="startEdit(selected)">修改草稿并记录原因</button><template v-if="selected.can_approve&&selected.status==='pending'"><label>确认意见{{ selected.risk>=3?'（必填）':'' }}<textarea v-model="note" class="input" rows="3" maxlength="1000"/></label><div class="ops-actions"><button class="btn primary" :disabled="busy||(selected.risk>=3&&!note.trim())" @click="decide('approve')">复验并批准</button><button class="btn" :disabled="busy" @click="decide('reject')">退回</button></div></template><p v-if="selected.decision_note">确认意见：{{ selected.decision_note }}</p></article></section>
<section v-if="tab==='executions'" class="card ops-panel"><h2>执行清单</h2><p v-if="!executions.length">暂无已批准的执行任务。</p><article v-for="item in executions" :key="item.id" class="ops-list-row"><div><b>{{ names[item.data.kind]||(item.data.kind==='meal_swap_prepare'?'换餐备餐清单':item.data.kind) }}</b><p v-if="item.resident_name"><b>{{ item.resident_name }}</b></p><p>{{ describe(item.data) }}</p><small>{{ states[item.status]||item.status }}</small></div><form v-if="['user','kitchen'].includes(card.role)&&item.status==='pending'" @submit.prevent="action(async()=>{await ops.post(`executions/${item.id}/complete`,{note:item.completionNote||''});executions=(await ops.list('executions')).items;notice='执行记录已保存。'})"><label>执行记录<input v-model="item.completionNote" class="input" maxlength="1000" required></label><button class="btn primary" :disabled="busy">确认完成</button></form></article></section>
<section v-if="tab==='shifts'" class="card ops-panel"><h2>排班与打卡</h2><p v-if="!shifts.length">暂无已批准的班次。</p><article v-for="s in shifts" :key="s.id" class="ops-list-row"><div><b>{{ s.start_at.replace('T',' ') }} 至 {{ s.end_at.replace('T',' ') }}</b><p>签到 {{ s.checked_in||'未签到' }} · 签退 {{ s.checked_out||'未签退' }}</p><p v-if="card.role==='finance'">小时费率 {{ s.hourly_rate }} 元</p></div><div v-if="card.role==='user'" class="ops-actions"><button class="btn" :disabled="busy||!!s.checked_in" @click="action(async()=>{await ops.post(`shifts/${s.id}/clock`,{action:'in'});shifts=(await ops.list('shifts')).items})">签到</button><button class="btn" :disabled="busy||!s.checked_in||!!s.checked_out" @click="action(async()=>{await ops.post(`shifts/${s.id}/clock`,{action:'out'});shifts=(await ops.list('shifts')).items})">签退</button></div></article></section>
<section v-if="tab==='profiles'" class="card ops-panel"><h2>结构化医护资料</h2><p class="ops-help">由专业人员核实已知过敏、疾病、在用药和个体一日营养目标。自由文本档案不会自动视为“已核实”。</p><div class="ops-grid"><label>老人<AppSelect v-model="target" class="select" @change="residentVersion=0"><option value="">请选择</option><option v-for="r in residents" :key="r.id" :value="r.id">{{ r.name }}</option></AppSelect></label><button class="btn" :disabled="busy" @click="loadProfile">读取资料</button></div><div v-if="recordExcerpt" class="ops-content"><b>档案原有记录（需专业核实）</b><p>过敏：{{ recordExcerpt.allergies||'未记录' }}</p><p>慢病：{{ recordExcerpt.chronic_conditions||'未记录' }}</p><p>饮食：{{ recordExcerpt.dietary_notes||'未记录' }}</p></div><form v-if="residentVersion" @submit.prevent="saveProfile"><fieldset class="ops-fieldset" :disabled="busy"><div class="ops-grid"><label>过敏原标识（明确无已知项时留空）<input v-model="allergens" class="input"></label><label>疾病标识（明确无已知项时留空）<input v-model="diseases" class="input"></label><label>每日能量下限（kcal）<input v-model="energyMin" class="input" type="number" min="1" required></label><label>每日能量上限（kcal）<input v-model="energyMax" class="input" type="number" min="1" required></label><label>每日蛋白下限（g）<input v-model="proteinMin" class="input" type="number" min="0" required></label><label>每日钠上限（mg）<input v-model="sodiumMax" class="input" type="number" min="1" required></label></div><h3>已核实在用药</h3><div v-for="(m,i) in meds" :key="i" class="ops-line"><label>药品标识<input v-model="m.drug_id" class="input"></label><label>单次mg<input v-model="m.mg_per_dose" class="input" type="number" step="0.01"></label><label>每日次数<input v-model.number="m.times_daily" class="input" type="number" min="1"></label><button type="button" class="btn" @click="meds.splice(i,1)">移除</button></div><button type="button" class="btn" @click="meds.push({drug_id:'',mg_per_dose:'',times_daily:1})">添加在用药</button><label>专业核实依据<textarea v-model="profileSource" class="input" maxlength="500" required/></label><label class="ops-checkbox"><input v-model="known" type="checkbox" required>我已逐项核实；空列表表示明确无已知项，而非资料未知。</label><button class="btn primary" :disabled="busy||!known">校验并保存</button></fieldset></form></section>
<section v-if="tab==='references'" class="card ops-panel"><h2>药品说明书原文定位</h2><p class="ops-help">先在用药安全知识库上传并切块，再将已核实的说明书条目关联到药品。检索会先按药品、类别和有效期过滤，原文变更后需重新核对。</p><form @submit.prevent="action(async()=>{await ops.post('drug-references',{drug_id:referenceDrug,chunk_id:Number(referenceChunk),section:referenceSection,valid_from:referenceFrom,valid_until:referenceUntil||null});notice='原文条目已关联。'})"><fieldset class="ops-fieldset ops-grid" :disabled="busy"><label>药品标识<input v-model="referenceDrug" class="input" maxlength="80" required></label><label>知识块编号<input v-model="referenceChunk" class="input" type="number" min="1" required></label><label>说明书条号<input v-model="referenceSection" class="input" maxlength="100" required></label><label>生效日期<input v-model="referenceFrom" class="input" type="date" required></label><label>失效日期（可留空）<input v-model="referenceUntil" class="input" type="date"></label><button class="btn primary">核对并关联原文</button></fieldset></form></section>
<section v-if="tab==='staff'" class="card ops-panel"><h2>岗位与资质授权</h2><p>先注册普通账号，再由院长核对任职与资质。变更后该账号需要重新登录。</p><form @submit.prevent="action(async()=>{await ops.put('staff',{account_id:staffTarget,role:newRole,qualification,valid_until:validUntil||null});staff=(await ops.list('staff')).items;notice='岗位已更新，该账号需重新登录。'})"><fieldset :disabled="busy" class="ops-fieldset ops-grid"><label>账号<AppSelect v-model="staffTarget" class="select"><option value="">请选择账号</option><option v-for="s in staff" :key="s.id" :value="s.id">{{ s.name }} · {{ s.phone_hint }} · {{ card.roles[s.role] }}</option></AppSelect></label><label>岗位<AppSelect v-model="newRole" class="select"><option v-for="(name,id) in card.roles" :key="id" :value="id">{{ name }}</option></AppSelect></label><label>资质或任职核实记录<input v-model="qualification" class="input" maxlength="80" :required="['medical','nursing'].includes(newRole)"></label><label>有效期<input v-model="validUntil" class="input" type="date" :required="['medical','nursing'].includes(newRole)"></label><button class="btn primary" :disabled="!staffTarget">保存授权</button></fieldset></form></section>
<section v-if="tab==='corrections'" class="card ops-panel"><h2>建议—修改—确认台账</h2><p v-if="!corrections.length">暂无人工修正。</p><article v-for="c in corrections" :key="c.id" class="ops-list-row"><div><b>{{ {rule:'规则维护',agent:'Agent改进',training:'人员培训'}[c.route as string] }} · {{ c.tag }}</b><p>{{ c.reason }}</p><details><summary>核对修改前后</summary><p>原建议：{{ describe(c.before) }}</p><p>修改后：{{ describe(c.after) }}</p></details><p>{{ c.closed?'已闭环':'待跟进' }}</p></div><form v-if="card.role==='admin'&&!c.closed" @submit.prevent="action(async()=>{await ops.post(`corrections/${c.id}/close`,{note:c.closeNote});corrections=(await ops.list('corrections')).items})"><label>闭环说明<input v-model="c.closeNote" class="input" required></label><button class="btn" :disabled="busy">记录闭环</button></form></article></section>
<section v-if="tab==='dashboard'&&dashboard" class="card ops-panel"><h2>运营与人工复核</h2><div class="ops-stats"><article v-for="s in [{label:'待审批',value:dashboard.pending},{label:'已批准',value:dashboard.approved},{label:'原建议直接采纳',value:dashboard.unchanged_adoption==null?'暂无样本':(dashboard.unchanged_adoption*100).toFixed(1)+'%'},{label:'待闭环修正',value:dashboard.open_corrections}]" :key="s.label"><b>{{ s.value }}</b><span>{{ s.label }}</span></article></div><p>近30天已记录的只读工具调用：成功 {{ dashboard.tool_successes }} 次，失败 {{ dashboard.tool_failures }} 次；成功率 {{ dashboard.tool_success_rate==null?'暂无样本':(dashboard.tool_success_rate*100).toFixed(1)+'%' }}（不含网关拒绝及无法写审计的数据库故障）。</p><p>近30天权限拦截 {{ dashboard.gateway_denials }} 次；规则拦截 {{ dashboard.validation_blocks }} 次。</p><p v-for="(s,id) in dashboard.periods" :key="id">{{ String(id)==='week'?'近7天':'近30天' }}：批准 {{ (s as any).approved }} 份，原样采纳 {{ (s as any).unchanged }} 份。</p><p class="ops-help">{{ dashboard.notice }}</p></section>
<section v-if="tab==='audit'" class="card ops-panel"><h2>内部操作留痕</h2><article v-for="a in audit" :key="a.id" class="ops-list-row"><div><b>{{ a.action }}</b><p>{{ dateText(a.created_at) }} · {{ a.object_id }}</p><p>{{ describe(a.data) }}</p></div></article></section>
</template></div></template>
<style scoped>
.operations{max-width:1400px;margin:auto}.ops-identity{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:28px 32px;background:linear-gradient(120deg,#e9f0ff,#f4f7ff);border:1px solid #dce6f7;border-radius:18px;margin:22px 0}.ops-kicker{color:var(--brand);font-size:12px;font-weight:600;letter-spacing:.12em}.ops-identity h2{font-size:23px;margin:10px 0}.ops-identity p,.ops-help{color:#526481;line-height:1.8}.ops-seal{display:grid;justify-items:center;gap:10px;font-size:12px;color:var(--brand-deep);flex:none}.ops-tabs,.ops-actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.ops-tabs{padding-bottom:14px;border-bottom:1px solid var(--line)}.ops-panel{padding:24px;margin-bottom:20px;min-width:0}.ops-panel h2{font-size:18px;margin:0 0 20px}.ops-panel h3{font-size:15px;margin:24px 0 12px}.ops-fieldset{border:0;margin:0;padding:0;min-width:0}.ops-panel label{display:grid;gap:8px;margin:12px 0;color:#334155;font-size:13px}.ops-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 20px;align-items:end}.ops-line{display:flex;flex-wrap:wrap;gap:12px;align-items:end}.ops-line label{flex:1;min-width:145px}.ops-line>.btn{margin-bottom:12px}.ops-stack{padding:14px 0}.ops-checkbox{display:flex!important;align-items:center}.ops-drafts{display:grid;grid-template-columns:minmax(260px,.75fr) minmax(0,1.6fr);gap:20px;align-items:start}.ops-draft-item{display:flex;justify-content:space-between;align-items:center;gap:14px;width:100%;min-height:68px;padding:14px 12px;border:0;border-bottom:1px solid var(--line);background:none;text-align:left;cursor:pointer;border-radius:8px;color:inherit}.ops-draft-item.chosen{background:#edf3ff}.ops-draft-item small{display:block;color:#64748b;margin-top:7px}.ops-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;background:#f6f8fc;border-radius:10px;padding:16px}.ops-alert{padding:14px 18px;border-radius:10px;background:#fff7e7;color:#85580c;line-height:1.8;margin:14px 0;overflow-wrap:anywhere}.ops-alert.error{background:#fff0f0;color:#a32f2f}.ops-alert.success{background:#eaf8f0;color:#24613e}.ops-list-row{display:flex;justify-content:space-between;gap:24px;padding:20px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.ops-list-row>div{min-width:0}.ops-list-row p{line-height:1.8}.ops-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.ops-stats article{padding:20px;border:1px solid var(--line);border-radius:12px;display:grid;gap:14px}.ops-stats b{font-size:27px;color:var(--brand-deep)}.ops-stats span{color:#64748b}.operations .btn{min-height:44px}.operations :focus-visible{outline:2px solid var(--brand);outline-offset:3px}details{margin:16px 0}summary{cursor:pointer;padding:8px 0}@media(max-width:1000px){.ops-drafts{grid-template-columns:1fr}.ops-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:640px){.ops-grid{grid-template-columns:1fr}.ops-identity{padding:20px}.ops-seal{display:none}.ops-list-row{flex-direction:column}.ops-panel{padding:18px}.ops-stats{grid-template-columns:1fr}}
</style>
